ent:[["الشركة الأم (Parent)","المنشأة المعدة للقوائم المجمعة","قوائم مجمعة (IFRS 10) وقوائم منفصلة (IAS 27)","سياسات المجموعة الموحدة، عملية التجميع، القيود العلوية (Top-side)."],["التابعة (Subsidiary)","سيطرة (السلطة + التعرض للعوائد المتغيرة + القدرة على التأثير)","تجميع كامل سطرًا بسطر مع حذف البينيات وإظهار NCI","توحيد السياسات والتواريخ، ترجمة العملات، الشهرة."],["الشركة الزميلة (Associate)","تأثير جوهري (غالبًا 20%–50%)","طريقة حقوق الملكية (IAS 28)","موثوقية قوائمها، حذف الأرباح غير المحققة بنسبة الحصة، الانخفاض."],["المشروع المشترك (Joint Venture)","سيطرة مشتركة وحقوق في صافي الأصول","طريقة حقوق الملكية (IFRS 11)","تحليل الترتيب المشترك."],["العملية المشتركة (Joint Operation)","سيطرة مشتركة وحقوق في الأصول والتزامات بالالتزامات","الاعتراف بالحصة من الأصول والالتزامات والإيرادات والمصروفات","مطابقة حسابات المشغل."],["المنشأة المهيكلة (Structured Entity)","سيطرة عبر الترتيبات التعاقدية","تجميع إذا وُجدت سيطرة","تحليل السيطرة الفعلية (De facto)."],["التابعة الأجنبية (Foreign Subsidiary)","سيطرة مع عملة وظيفية مختلفة","ترجمة وفق IAS 21 وFCTR","أسعار الصرف، قيود التحويل، الاقتصادات ذات التضخم المفرط."]],
